#!/usr/bin/env bash
#
# Wires release signing into the generated Android project.
#
# A Flutter project generated by `flutter create .` has no release signing config,
# so `flutter build apk --release` falls back to the debug key - which Play
# rejects. This script adds a real signingConfig and creates key.properties.
#
# Run after `flutter create .`:
#
#   ./tool/configure_signing.sh
#
# In CI, provide the keystore and passwords through environment variables and the
# script writes everything itself:
#
#   ANDROID_KEYSTORE_BASE64   base64 of the .jks (decoded to android/app/upload-keystore.jks)
#   ANDROID_KEYSTORE_PASSWORD
#   ANDROID_KEY_PASSWORD
#   ANDROID_KEY_ALIAS         defaults to "upload"
#
# It is idempotent: a project that is already configured is left untouched.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ANDROID_DIR="$ROOT/android"
KEY_PROPERTIES="$ANDROID_DIR/key.properties"
KEYSTORE_PATH="$ANDROID_DIR/app/upload-keystore.jks"

if [ ! -d "$ANDROID_DIR" ]; then
  echo "error: android/ not found. Run 'flutter create --platforms=android .' first." >&2
  exit 1
fi

GRADLE_FILE=""
for candidate in "$ANDROID_DIR/app/build.gradle.kts" "$ANDROID_DIR/app/build.gradle"; do
  if [ -f "$candidate" ]; then GRADLE_FILE="$candidate"; break; fi
done
if [ -z "$GRADLE_FILE" ]; then
  echo "error: no android/app/build.gradle(.kts) found." >&2
  exit 1
fi

# ---------------------------------------------------------------- keystore
if [ -n "${ANDROID_KEYSTORE_BASE64:-}" ]; then
  echo "$ANDROID_KEYSTORE_BASE64" | base64 --decode > "$KEYSTORE_PATH"
  chmod 600 "$KEYSTORE_PATH"
  echo "keystore: decoded from ANDROID_KEYSTORE_BASE64 -> ${KEYSTORE_PATH#$ROOT/}"
fi

# ------------------------------------------------------------ key.properties
if [ ! -f "$KEY_PROPERTIES" ]; then
  if [ -z "${ANDROID_KEYSTORE_PASSWORD:-}" ] || [ -z "${ANDROID_KEY_PASSWORD:-}" ]; then
    cp "$ANDROID_DIR/key.properties.example" "$KEY_PROPERTIES"
    chmod 600 "$KEY_PROPERTIES"
    echo "warning: no passwords in the environment; wrote a placeholder" >&2
    echo "         android/key.properties. Fill it in before a release build." >&2
  else
    cat > "$KEY_PROPERTIES" <<EOF
storePassword=${ANDROID_KEYSTORE_PASSWORD}
keyPassword=${ANDROID_KEY_PASSWORD}
keyAlias=${ANDROID_KEY_ALIAS:-upload}
storeFile=upload-keystore.jks
EOF
    chmod 600 "$KEY_PROPERTIES"
    echo "key.properties: written from environment"
  fi
else
  echo "key.properties: already present, left untouched"
fi

# --------------------------------------------------------------- gradle block
python3 - "$GRADLE_FILE" <<'PY'
import re, sys

path = sys.argv[1]
src = open(path).read()
kotlin = path.endswith('.kts')

if 'signingConfigs' in src and 'upload-keystore.jks' in src:
    print("gradle: signing config already present")
    sys.exit(0)

if kotlin:
    loader = '''
// --- Sproutly release signing (added by tool/configure_signing.sh) ---
import java.util.Properties
import java.io.FileInputStream

val keystoreProperties = Properties()
val keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(FileInputStream(keystorePropertiesFile))
}
// --- end Sproutly release signing ---
'''
    signing = '''
    signingConfigs {
        create("release") {
            keyAlias = keystoreProperties["keyAlias"] as String?
            keyPassword = keystoreProperties["keyPassword"] as String?
            storeFile = keystoreProperties["storeFile"]?.let { file(it) }
            storePassword = keystoreProperties["storePassword"] as String?
        }
    }
'''
    build_type_patch = ('buildTypes {', 'buildTypes {\n        getByName("release") {\n            signingConfig = signingConfigs.getByName("release")\n        }')
else:
    loader = '''
// --- Sproutly release signing (added by tool/configure_signing.sh) ---
def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}
// --- end Sproutly release signing ---
'''
    signing = '''
    signingConfigs {
        release {
            keyAlias keystoreProperties['keyAlias']
            keyPassword keystoreProperties['keyPassword']
            storeFile keystoreProperties['storeFile'] ? file(keystoreProperties['storeFile']) : null
            storePassword keystoreProperties['storePassword']
        }
    }
'''
    build_type_patch = ('buildTypes {', "buildTypes {\n        release {\n            signingConfig signingConfigs.release\n        }")

# loader goes above the android { } block
anchor = re.search(r'^android\s*\{', src, re.M)
if not anchor:
    print("error: could not find the android { } block; add the signing config manually", file=sys.stderr)
    sys.exit(2)
src = src[:anchor.start()] + loader.strip() + "\n\n" + src[anchor.start():]

# signingConfigs before buildTypes
if 'buildTypes {' not in src:
    print("error: could not find buildTypes; add the signing config manually", file=sys.stderr)
    sys.exit(2)
src = src.replace('buildTypes {', signing.strip('\n') + '\n\n    buildTypes {', 1)

# a release block inside buildTypes, if one exists, gets the signingConfig;
# otherwise insert one
build_types_start = src.index('buildTypes {')
build_types_end = src.index('\n    }', build_types_start)
block = src[build_types_start:build_types_end]
# The generated template points release at the debug key. Drop that line, or it
# would silently win over the signing config we are about to add.
block = re.sub(r'\n\s*signingConfig\s*=?\s*signingConfigs\.debug\b.*', '', block)

has_release = re.search(r'release\s*\{', block) is not None
if has_release:
    if kotlin:
        block = re.sub(r'release\s*\{', 'release {\n            signingConfig = signingConfigs.getByName("release")', block, count=1)
    else:
        block = re.sub(r'release\s*\{', 'release {\n            signingConfig signingConfigs.release', block, count=1)
    src = src[:build_types_start] + block + src[build_types_end:]
else:
    insert = '\n        release {\n            signingConfig = signingConfigs.getByName("release")\n        }' if kotlin else "\n        release {\n            signingConfig signingConfigs.release\n        }"
    src = src[:build_types_end] + insert + src[build_types_end:]

open(path, 'w').write(src)
print(f"gradle: signing config added to {path.rsplit('/', 2)[-2]}/{path.rsplit('/', 1)[-1]}")
PY

echo
echo "Signing configured. Verify with:"
echo "  cd android && ./gradlew signingReport"
